export class FirmwareDisplay {
 constructor(ctx,texture){this.ctx=ctx;this.texture=texture;this.mask=0;this.pressedAt={};this.releaseAt={};this.ready=false;this.busy=false;this.on=false;this.elapsed=0;this.worker=new Worker(new URL('./emulator/worker.js',import.meta.url));this.worker.onmessage=({data})=>{if(data.ready){this.ready=true;return}this.busy=false;if(this.on){ctx.putImageData(new ImageData(new Uint8ClampedArray(data.pixels),360,360),0,0);texture.needsUpdate=true;document.querySelector('#scene').dataset.firmwareMode=data.mode;}};this.worker.onerror=e=>console.error('Badge firmware:',e.message);this.clear();}
 clear(){this.ctx.fillStyle='#030406';this.ctx.fillRect(0,0,360,360);this.texture.needsUpdate=true;}
 hold(bit,on){if(on){this.pressedAt[bit]=performance.now();delete this.releaseAt[bit];this.mask|=bit;}else this.releaseAt[bit]=Math.max(performance.now(),(this.pressedAt[bit]||0)+100);}
 release(){for(const bit of [1,2,4])if(this.mask&bit)this.hold(bit,false);}
 tick(dt,on){for(const bit of [1,2,4])if(this.releaseAt[bit]&&performance.now()>=this.releaseAt[bit]){this.mask&=~bit;delete this.releaseAt[bit];}if(on!==this.on){this.on=on;this.mask=0;this.elapsed=0;if(this.ready)this.worker.postMessage({reset:true});if(!on)this.clear();}if(!on||!this.ready)return;this.elapsed+=dt*1000;if(!this.busy){this.busy=true;this.worker.postMessage({dt:Math.min(this.elapsed,100),mask:this.mask});this.elapsed=0;}}
 bind(element,bit){element.addEventListener('pointerdown',e=>{element.setPointerCapture(e.pointerId);this.hold(bit,true)});for(const event of ['pointerup','pointercancel','lostpointercapture'])element.addEventListener(event,()=>this.hold(bit,false));element.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();this.hold(bit,true)}});element.addEventListener('keyup',()=>this.hold(bit,false));element.addEventListener('blur',()=>this.hold(bit,false));}
}
